begin;
    with j as (select * from jsonb_to_recordset($law7v014$[{"code_id":"GK_RF_2","article_number":"583","version_date":"1994-11-30","article_text":"1. По договору ренты одна сторона (получатель ренты) передает другой стороне (плательщику ренты) в собственность имущество, а плательщик ренты обязуется в обмен на полученное имущество периодически выплачивать получателю ренту в виде определенной денежной суммы либо предоставления средств на его содержание в иной форме.\n\n2. По договору ренты допускается установление обязанности выплачивать ренту бессрочно (постоянная рента) или на срок жизни получателя ренты (пожизненная рента). Пожизненная рента может быть установлена на условиях пожизненного содержания гражданина с иждивением.","article_title":"Статья 583. Договор ренты","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d1f2a0f0c572ce43e6e917e936d4a394e95d88a67f446991434863cc111c8f1e"},{"code_id":"GK_RF_2","article_number":"584","version_date":"1994-11-30","article_text":"Договор ренты подлежит нотариальному удостоверению, а договор, предусматривающий отчуждение недвижимого имущества под выплату ренты, подлежит также государственной регистрации.","article_title":"Статья 584. Форма договора ренты","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1548118d22dddfe4ee1b9b8e57fa2fe227fe9e7b198be5299e07166c1a887175"},{"code_id":"GK_RF_2","article_number":"585","version_date":"1994-11-30","article_text":"1. Имущество, которое отчуждается под выплату ренты, может быть передано получателем ренты в собственность плательщика ренты за плату или бесплатно.\n\n2. В случае, когда договором ренты предусматривается передача имущества за плату, к отношениям сторон по передаче и оплате применяются правила о купле-продаже (глава 30), а в случае, когда такое имущество передается бесплатно, правила о договоре дарения (глава 32) постольку, поскольку иное не установлено правилами настоящей главы и не противоречит существу договора ренты.","article_title":"Статья 585. Отчуждение имущества под выплату ренты","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f572b1f63a36f975eada3f4ef9cadebb4a537439b43907169298aac2b198bc1c"},{"code_id":"GK_RF_2","article_number":"586","version_date":"1994-11-30","article_text":"1. Рента обременяет земельный участок, предприятие, здание, сооружение или другое недвижимое имущество, переданное под ее выплату. В случае отчуждения такого имущества плательщиком ренты его обязательства по договору ренты переходят на приобретателя имущества.\n\n2. Лицо, передавшее обремененное рентой недвижимое имущество в собственность другого лица, несет субсидиарную с ним ответственность (статья 399) по требованиям получателя ренты, возникшим в связи с нарушением договора ренты, если настоящим Кодексом, другим законом или договором не предусмотрена солидарная ответственность по этому обязательству.","article_title":"Статья 586. Обременение рентой недвижимого имущества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a14f60888441f498164e9e7b05586f583542d610b4515e1107299cdcebccaecc"},{"code_id":"GK_RF_2","article_number":"587","version_date":"1994-11-30","article_text":"1. При передаче под выплату ренты земельного участка или другого недвижимого имущества получатель ренты в обеспечение обязательства плательщика ренты приобретает право залога на это имущество.\n\n2. Существенным условием договора, предусматривающего передачу под выплату ренты денежной суммы или иного движимого имущества, является условие, устанавливающее обязанность плательщика ренты предоставить обеспечение исполнения его обязательств (статья 329) либо застраховать в пользу получателя ренты риск ответственности за неисполнение либо ненадлежащее исполнение этих обязательств.\n\n3. При невыполнении плательщиком ренты обязанностей, предусмотренных пунктом 2 настоящей статьи, а также в случае утраты обеспечения или ухудшения его условий по обстоятельствам, за которые получатель ренты не отвечает, получатель ренты вправе расторгнуть договор ренты и потребовать возмещения убытков, вызванных расторжением договора.","article_title":"Статья 587. Обеспечение выплаты ренты","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8cb603d913cc2eb13a4474b87169d802723985a821e8d468e5747d7f6e9b55c7"},{"code_id":"GK_RF_2","article_number":"588","version_date":"1994-11-30","article_text":"За просрочку выплаты ренты плательщик ренты уплачивает получателю ренты проценты, предусмотренные статьей 395 настоящего Кодекса, если иной размер процентов не установлен договором ренты.","article_title":"Статья 588. Ответственность за просрочку выплаты ренты","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9280065860ac224f8373cb3cf9fcb18c12a3ca34e502b789aec547f146191b10"},{"code_id":"GK_RF_2","article_number":"589","version_date":"1994-11-30","article_text":"1. Получателями постоянной ренты могут быть только граждане, а также некоммерческие организации, если это не противоречит закону и соответствует целям их деятельности.\n\n2. Права получателя ренты по договору постоянной ренты могут передаваться лицам, указанным в пункте 1 настоящей статьи, путем уступки требования и переходить по наследству либо в порядке правопреемства при реорганизации юридических лиц, если иное не предусмотрено законом или договором.","article_title":"Статья 589. Получатель постоянной ренты","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"77456a2944d588eddfa662fd1308893d7c19d9008d1e16a3cb39e24a01e44e54"},{"code_id":"GK_RF_2","article_number":"590","version_date":"1994-11-30","article_text":"1. Постоянная рента выплачивается в деньгах в размере, устанавливаемом договором.\n\nДоговором постоянной ренты может быть предусмотрена выплата ренты путем предоставления вещей, выполнения работ или оказания услуг, соответствующих по стоимости денежной сумме ренты.\n\n2. Размер выплачиваемой постоянной ренты, установленный договором постоянной ренты, в расчете на месяц должен быть не менее установленной в соответствии с законом величины прожиточного минимума на душу населения в соответствующем субъекте Российской Федерации по месту нахождения имущества, являющегося предметом договора постоянной ренты, а при отсутствии в соответствующем субъекте Российской Федерации указанной величины не менее установленной в соответствии с законом величины прожиточного минимума на душу населения в целом по Российской Федерации.\n\nРазмер постоянной ренты, установленный договором постоянной ренты на уровне указанной в абзаце первом настоящего пункта величины прожиточного минимума на душу населения, подлежит увеличению с учетом роста соответствующей величины прожиточного минимума на душу населения.\n\n(Пункт в редакции Федерального закона от 30.11.2011 № 363-ФЗ)","article_title":"Статья 590. Форма и размер постоянной ренты","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0c544f0c423a396b88bd61d8073e67dabb9757a47e57c575db6a1a988e2d98ff"},{"code_id":"GK_RF_2","article_number":"591","version_date":"1994-11-30","article_text":"Если иное не предусмотрено договором постоянной ренты, постоянная рента выплачивается по окончании каждого календарного квартала.","article_title":"Статья 591. Сроки выплаты постоянной ренты","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c8fe757f6561fe1c152ad7270fcfd617eaf0b2298f929b447e15e56b8a504e4f"},{"code_id":"GK_RF_2","article_number":"592","version_date":"1994-11-30","article_text":"1. Плательщик постоянной ренты вправе отказаться от дальнейшей выплаты ренты путем ее выкупа.\n\n2. Такой отказ действителен при условии, что он заявлен плательщиком ренты в письменной форме не позднее чем за три месяца до прекращения выплаты ренты или за более длительный срок, предусмотренный договором постоянной ренты. При этом обязательство по выплате ренты не прекращается до получения всей суммы выкупа получателем ренты, если иной порядок выкупа не предусмотрен договором.\n\n3. Условие договора постоянной ренты об отказе плательщика постоянной ренты от права на ее выкуп ничтожно.\n\nДоговором может быть предусмотрено, что право на выкуп постоянной ренты не может быть осуществлено при жизни получателя ренты либо в течение иного срока, не превышающего тридцати лет с момента заключения договора.","article_title":"Статья 592. Право плательщика на выкуп постоянной ренты","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0023c180a888a39847fe7e7f494ec32c7b155dfb3d735a80e5d9f2661528936a"},{"code_id":"GK_RF_2","article_number":"593","version_date":"1994-11-30","article_text":"Получатель постоянной ренты вправе требовать выкупа ренты плательщиком в случаях, когда:\n\nплательщик ренты просрочил ее выплату более чем на один год, если иное не предусмотрено договором постоянной ренты;\n\nплательщик ренты нарушил свои обязательства по обеспечению выплаты ренты (статья 587);\n\nплательщик ренты признан неплатежеспособным либо возникли иные обстоятельства, очевидно свидетельствующие, что рента не будет выплачиваться им в размере и в сроки, которые установлены договором;\n\nнедвижимое имущество, переданное под выплату ренты, поступило в общую собственность или разделено между несколькими лицами;\n\nв других случаях, предусмотренных договором.","article_title":"Статья 593. Выкуп постоянной ренты по требованию получателя ренты","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d21c855c7478223b2642a9da2a18fabca9033086988e7c8103b5727769825456"},{"code_id":"GK_RF_2","article_number":"594","version_date":"1994-11-30","article_text":"1. Выкуп постоянной ренты в случаях, предусмотренных статьями 592 и 593 настоящего Кодекса, производится по цене, определенной договором постоянной ренты.\n\n2. При отсутствии условия о выкупной цене в договоре постоянной ренты, по которому имущество передано за плату под выплату постоянной ренты, выкуп осуществляется по цене, соответствующей годовой сумме подлежащей выплате ренты.\n\n3. При отсутствии условия о выкупной цене в договоре постоянной ренты, по которому имущество передано под выплату ренты бесплатно, в выкупную цену наряду с годовой суммой рентных платежей включается цена переданного имущества, определяемая по правилам, предусмотренным пунктом 3 статьи 424 настоящего Кодекса.","article_title":"Статья 594. Выкупная цена постоянной ренты","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2bdb30442df24a361dcb07a9ccdbec6b3d3042973697384e5f9bbac9b1859aef"},{"code_id":"GK_RF_2","article_number":"595","version_date":"1994-11-30","article_text":"1. Риск случайной гибели или случайного повреждения имущества, переданного бесплатно под выплату постоянной ренты, несет плательщик ренты.\n\n2. При случайной гибели или случайном повреждении имущества, переданного за плату под выплату постоянной ренты, плательщик вправе требовать соответственно прекращения обязательства по выплате ренты либо изменения условий ее выплаты.","article_title":"Статья 595. Риск случайной гибели имущества, переданного под выплату постоянной ренты","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2b374f2a42464b9a228abc8d07b8cebc6d85b2b2678d7bdb9bde1aa91af1087e"},{"code_id":"GK_RF_2","article_number":"596","version_date":"1994-11-30","article_text":"1. Пожизненная рента может быть установлена на период жизни гражданина, передающего имущество под выплату ренты, либо на период жизни другого указанного им гражданина.\n\n2. Допускается установление пожизненной ренты в пользу нескольких граждан, доли которых в праве на получение ренты считаются равными, если иное не предусмотрено договором пожизненной ренты.\n\nВ случае смерти одного из получателей ренты его доля в праве на получение ренты переходит к пережившим его получателям ренты, если договором пожизненной ренты не предусмотрено иное, а в случае смерти последнего получателя ренты обязательство выплаты ренты прекращается.\n\n3. Договор, устанавливающий пожизненную ренту в пользу гражданина, который умер к моменту заключения договора, ничтожен.","article_title":"Статья 596. Получатель пожизненной ренты","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8a5be71d99dc31ce849ff5ffb756bef6843a5420aff6f2f65703e394c3db0ee0"},{"code_id":"GK_RF_2","article_number":"597","version_date":"1994-11-30","article_text":"1. Пожизненная рента определяется в договоре как денежная сумма, периодически выплачиваемая получателю ренты в течение его жизни.\n\n2. Размер пожизненной ренты, установленный договором пожизненной ренты, предусматривающим отчуждение имущества бесплатно, в расчете на месяц должен быть не менее установленной в соответствии с законом величины прожиточного минимума на душу населения в соответствующем субъекте Российской Федерации по месту нахождения имущества, являющегося предметом договора пожизненной ренты, а при отсутствии в соответствующем субъекте Российской Федерации указанной величины не менее установленной в соответствии с законом величины прожиточного минимума на душу населения в целом по Российской Федерации.\n\nРазмер пожизненной ренты, установленный договором пожизненной ренты на уровне указанной в абзаце первом настоящего пункта величины прожиточного минимума на душу населения, подлежит увеличению с учетом роста соответствующей величины прожиточного минимума на душу населения.\n\n(Пункт в редакции Федерального закона от 30.11.2011 № 363-ФЗ)","article_title":"Статья 597. Размер пожизненной ренты","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"abc5e32fbb9367fd18652317bc5054b38ad311ab513e8d4630f43ef4ddbb2adb"},{"code_id":"GK_RF_2","article_number":"598","version_date":"1994-11-30","article_text":"Если иное не предусмотрено договором пожизненной ренты, пожизненная рента выплачивается по окончании каждого календарного месяца.","article_title":"Статья 598. Сроки выплаты пожизненной ренты","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"11a4af88f9e2d2b183bec3330ae789a57412c5b7dd4f8949f0efd1dd9224617e"},{"code_id":"GK_RF_2","article_number":"599","version_date":"1994-11-30","article_text":"1. В случае существенного нарушения договора пожизненной ренты плательщиком ренты получатель ренты вправе требовать от плательщика ренты выкупа ренты на условиях, предусмотренных статьей 594 настоящего Кодекса, либо расторжения договора и возмещения убытков.\n\n2. Если под выплату пожизненной ренты квартира, жилой дом или иное имущество отчуждены бесплатно, получатель ренты вправе при существенном нарушении договора плательщиком ренты потребовать возврата этого имущества с зачетом его стоимости в счет выкупной цены ренты.","article_title":"Статья 599. Расторжение договора пожизненной ренты по требованию получателя ренты","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b2323085f124f850f184a1caeb4dd9e2be16bdd14054e31719c4e25c05086ddd"},{"code_id":"GK_RF_2","article_number":"600","version_date":"1994-11-30","article_text":"Случайная гибель или случайное повреждение имущества, переданного под выплату пожизненной ренты, не освобождают плательщика ренты от обязательства выплачивать ее на условиях, предусмотренных договором пожизненной ренты.","article_title":"Статья 600. Риск случайной гибели имущества, переданного под выплату пожизненной ренты","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"09cfe534a6e9c6cb534e93e0a378ef46d3490cb06e20e8daaf8cd2326d365e69"},{"code_id":"GK_RF_2","article_number":"601","version_date":"1994-11-30","article_text":"1. По договору пожизненного содержания с иждивением получатель ренты - гражданин передает принадлежащие ему жилой дом, квартиру, земельный участок или иную недвижимость в собственность плательщика ренты, который обязуется осуществлять пожизненное содержание с иждивением гражданина и (или) указанного им третьего лица (лиц).\n\n2. К договору пожизненного содержания с иждивением применяются правила о пожизненной ренте, если иное не предусмотрено правилами настоящего параграфа.","article_title":"Статья 601. Договор пожизненного содержания с иждивением","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"217351f04a0977105874fb97cd9ccc66fc7d67addef1c9024f88ab6978398d8d"},{"code_id":"GK_RF_2","article_number":"602","version_date":"1994-11-30","article_text":"1. Обязанность плательщика ренты по предоставлению содержания с иждивением может включать обеспечение потребностей в жилище, питании и одежде, а если этого требует состояние здоровья гражданина, также и уход за ним. Договором пожизненного содержания с иждивением может быть также предусмотрена оплата плательщиком ренты ритуальных услуг.\n\n2. В договоре пожизненного содержания с иждивением должна быть определена стоимость всего объема содержания с иждивением. При этом стоимость общего объема содержания в месяц по договору пожизненного содержания с иждивением, предусматривающему отчуждение имущества бесплатно, не может быть менее двух установленных в соответствии с законом величин прожиточного минимума на душу населения в соответствующем субъекте Российской Федерации по месту нахождения имущества, являющегося предметом договора пожизненного содержания с иждивением, а при отсутствии в соответствующем субъекте Российской Федерации указанной величины не менее\n\nдвух установленных в соответствии с законом величин прожиточного минимума на душу населения в целом по Российской Федерации. (В редакции Федерального закона от 30.11.2011 № 363-ФЗ)\n\n3. При разрешении спора между сторонами об объеме содержания, которое предоставляется или должно предоставляться гражданину, суд должен руководствоваться принципами добросовестности и разумности.","article_title":"Статья 602. Обязанность по предоставлению содержания с иждивением","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"48343e441a7e6bb5772e940786418d18143b4fd6ce32d6273604388b37c9a97a"},{"code_id":"GK_RF_2","article_number":"603","version_date":"1994-11-30","article_text":"Договором пожизненного содержания с иждивением может быть предусмотрена возможность замены предоставления содержания с иждивением в натуре выплатой в течение жизни гражданина периодических платежей в деньгах.","article_title":"Статья 603. Замена пожизненного содержания периодическими платежами","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7341a9f66bb6c401de5e0db7276f38930783526f5de2c3d30e7e5198dbd1fdce"},{"code_id":"GK_RF_2","article_number":"604","version_date":"1994-11-30","article_text":"Плательщик ренты вправе отчуждать, сдавать в залог или иным способом обременять недвижимое имущество, переданное ему в обеспечение пожизненного содержания, только с предварительного согласия получателя ренты.\n\nПлательщик ренты обязан принимать необходимые меры для того, чтобы в период предоставления пожизненного содержания с иждивением использование указанного имущества не приводило к снижению стоимости этого имущества.","article_title":"Статья 604. Отчуждение и использование имущества, переданного для обеспечения пожизненного содержания","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"21713c08d89d24ba4799d7f79a724df1939f4ef5aca2a74055cbaedee9bf5cdc"},{"code_id":"GK_RF_2","article_number":"605","version_date":"1994-11-30","article_text":"1. Обязательство пожизненного содержания с иждивением прекращается смертью получателя ренты.\n\n2. При существенном нарушении плательщиком ренты своих обязательств получатель ренты вправе потребовать возврата недвижимого имущества, переданного в обеспечение пожизненного содержания, либо выплаты ему выкупной цены на условиях, установленных статьей 594 настоящего Кодекса. При этом плательщик ренты не вправе требовать компенсацию расходов, понесенных в связи с содержанием получателя ренты.","article_title":"Статья 605. Прекращение пожизненного содержания с иждивением","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4ce6f1844808a8c5b9cb1f4c1c4fee0b67732208e9e06f17b0f8091ef9a748a6"},{"code_id":"GK_RF_2","article_number":"606","version_date":"1994-11-30","article_text":"По договору аренды (имущественного найма) арендодатель (наймодатель) обязуется предоставить арендатору (нанимателю) имущество за плату во временное владение и пользование или во временное пользование.\n\nПлоды, продукция и доходы, полученные арендатором в результате использования арендованного имущества в соответствии с договором, являются его собственностью.","article_title":"Статья 606. Договор аренды","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"91c137dc1377d30e9ba405917cc26ddfac4c931483240116987a5851146ed240"},{"code_id":"GK_RF_2","article_number":"607","version_date":"1994-11-30","article_text":"1. В аренду могут быть переданы земельные участки и другие обособленные природные объекты, предприятия и другие имущественные комплексы, здания, сооружения, оборудование, транспортные средства и другие вещи, которые не теряют своих натуральных свойств в процессе их использования (непотребляемые вещи).\n\nЗаконом могут быть установлены виды имущества, сдача которого в аренду не допускается или ограничивается.\n\n2. Законом могут быть установлены особенности сдачи в аренду земельных участков и других обособленных природных объектов.\n\n3. В договоре аренды должны быть указаны данные, позволяющие определенно установить имущество, подлежащее передаче арендатору в качестве объекта аренды. При отсутствии этих данных в договоре условие об объекте, подлежащем передаче в аренду, считается не согласованным сторонами, а соответствующий договор не считается заключенным.","article_title":"Статья 607. Объекты аренды","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"813a6362dd4e0d8e4145fffe6ca4abf9f95a0cdcc957d56ba724627b26928f38"},{"code_id":"GK_RF_2","article_number":"608","version_date":"1994-11-30","article_text":"Право сдачи имущества в аренду принадлежит его собственнику. Арендодателями могут быть также лица, управомоченные законом или собственником сдавать имущество в аренду.","article_title":"Статья 608. Арендодатель","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"54e6151d3bf8a3005ed717f69481bd72a5d23d07a48ddd10fbb5bd630d46b265"},{"code_id":"GK_RF_2","article_number":"609","version_date":"1994-11-30","article_text":"1. Договор аренды на срок более года, а если хотя бы одной из сторон договора является юридическое лицо, независимо от срока, должен быть заключен в письменной форме.\n\n2. Договор аренды недвижимого имущества подлежит государственной регистрации, если иное не установлено законом.\n\n3. Договор аренды имущества, предусматривающий переход в последующем права собственности на это имущество к арендатору (статья 624), заключается в форме, предусмотренной для договора купли-продажи такого имущества.","article_title":"Статья 609. Форма и государственная регистрация договора аренды","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"69728120ccd4b57b1d5131fbce6f3bb49e457ab45d42e03c6a7d83743a4bedc8"},{"code_id":"GK_RF_2","article_number":"610","version_date":"1994-11-30","article_text":"1. Договор аренды заключается на срок, определенный договором.\n\n2. Если срок аренды в договоре не определен, договор аренды считается заключенным на неопределенный срок.\n\nВ этом случае каждая из сторон вправе в любое время отказаться от договора, предупредив об этом другую сторону за один месяц, а при аренде недвижимого имущества за три месяца. Законом или договором может быть установлен иной срок для предупреждения о прекращении договора аренды, заключенного на неопределенный срок.\n\n3. Законом могут устанавливаться максимальные (предельные) сроки договора для отдельных видов аренды, а также для аренды отдельных видов имущества. В этих случаях, если срок аренды в договоре не определен и ни одна из сторон не отказалась от договора до истечения предельного срока, установленного законом, договор по истечении предельного срока прекращается.\n\nДоговор аренды, заключенный на срок, превышающий установленный законом предельный срок, считается заключенным на срок, равный предельному.","article_title":"Статья 610. Срок договора аренды","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"44e618619bef935fdf0674dd5b8ca523c02b198e0423db9e1e68694c25c374ea"},{"code_id":"GK_RF_2","article_number":"611","version_date":"1994-11-30","article_text":"1. Арендодатель обязан предоставить арендатору имущество в состоянии, соответствующем условиям договора аренды и назначению имущества.\n\n2. Имущество сдается в аренду вместе со всеми его принадлежностями и относящимися к нему документами (техническим паспортом, сертификатом качества и т.п.), если иное не предусмотрено договором.\n\nЕсли такие принадлежности и документы переданы не были, однако без них арендатор не может пользоваться имуществом в соответствии с его назначением либо в значительной степени лишается того, на что был вправе рассчитывать при заключении договора, он может потребовать предоставления ему арендодателем таких принадлежностей и документов или расторжения договора, а также возмещения убытков.\n\n3. Если арендодатель не предоставил арендатору сданное внаем имущество в указанный в договоре аренды срок, а в случае, когда в договоре такой срок не указан, в разумный срок, арендатор вправе истребовать от него это имущество в соответствии со статьей 398 настоящего Кодекса и потребовать возмещения убытков, причиненных задержкой исполнения, либо потребовать расторжения договора и возмещения убытков, причиненных его неисполнением.","article_title":"Статья 611. Предоставление имущества арендатору","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5d7ceba2786c10fde3483b627140eb6a0929c3f0f3ee96568ed7bb23dabc8251"},{"code_id":"GK_RF_2","article_number":"612","version_date":"1994-11-30","article_text":"1. Арендодатель отвечает за недостатки сданного в аренду имущества, полностью или частично препятствующие пользованию им, даже если во время заключения договора аренды он не знал об этих недостатках.\n\nПри обнаружении таких недостатков арендатор вправе по своему выбору:\n\nпотребовать от арендодателя либо безвозмездного устранения недостатков имущества, либо соразмерного уменьшения арендной платы, либо возмещения своих расходов на устранение недостатков имущества;\n\nнепосредственно удержать сумму понесенных им расходов на устранение данных недостатков из арендной платы, предварительно уведомив об этом арендодателя;\n\nпотребовать досрочного расторжения договора.\n\nАрендодатель, извещенный о требованиях арендатора или о его намерении устранить недостатки имущества за счет арендодателя, может без промедления произвести замену предоставленного арендатору имущества другим аналогичным имуществом, находящимся в надлежащем состоянии, либо безвозмездно устранить недостатки имущества.\n\nЕсли удовлетворение требований арендатора или удержание им расходов на устранение недостатков из арендной платы не покрывает причиненных арендатору убытков, он вправе потребовать возмещения непокрытой части убытков.\n\n2. Арендодатель не отвечает за недостатки сданного в аренду имущества, которые были им оговорены при заключении договора аренды или были заранее известны арендатору либо должны были быть обнаружены арендатором во время осмотра имущества или проверки его исправности при заключении договора или передаче имущества в аренду.","article_title":"Статья 612. Ответственность арендодателя за недостатки сданного в аренду имущества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d525071ff9d0d1d1aa9bc78732570b24caef06d883744e4c68352eb67d99c1c4"},{"code_id":"GK_RF_2","article_number":"613","version_date":"1994-11-30","article_text":"Передача имущества в аренду не является основанием для прекращения или изменения прав третьих лиц на это имущество.\n\nПри заключении договора аренды арендодатель обязан предупредить арендатора о всех правах третьих лиц на сдаваемое в аренду имущество (сервитуте, праве залога и т.п.). Неисполнение арендодателем этой обязанности дает арендатору право требовать уменьшения арендной платы либо расторжения договора и возмещения убытков.","article_title":"Статья 613. Права третьих лиц на сдаваемое в аренду имущество","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0a8c8454508f812122d58e99959276e5567bf36a675677db42f9a5cdde39a812"},{"code_id":"GK_RF_2","article_number":"614","version_date":"1994-11-30","article_text":"1. Арендатор обязан своевременно вносить плату за пользование имуществом (арендную плату).\n\nПорядок, условия и сроки внесения арендной платы определяются договором аренды. В случае, когда договором они не определены, считается, что установлены порядок, условия и сроки, обычно применяемые при аренде аналогичного имущества при сравнимых обстоятельствах.\n\n2. Арендная плата устанавливается за все арендуемое имущество в целом или отдельно по каждой из его составных частей в виде:\n\n1) определенных в твердой сумме платежей, вносимых периодически или единовременно;\n\n2) установленной доли полученных в результате использования арендованного имущества продукции, плодов или доходов;\n\n3) предоставления арендатором определенных услуг;\n\n4) передачи арендатором арендодателю обусловленной договором вещи в собственность или в аренду;\n\n5) возложения на арендатора обусловленных договором затрат на улучшение арендованного имущества.\n\nСтороны могут предусматривать в договоре аренды сочетание указанных форм арендной платы или иные формы оплаты аренды.\n\n3. Если иное не предусмотрено договором, размер арендной платы может изменяться по соглашению сторон в сроки, предусмотренные договором, но не чаще одного раза в год. Законом могут быть предусмотрены иные минимальные сроки пересмотра размера арендной платы для отдельных видов аренды, а также для аренды отдельных видов имущества.\n\n4. Если законом не предусмотрено иное, арендатор вправе потребовать соответственного уменьшения арендной платы, если в силу обстоятельств, за которые он не отвечает, условия пользования, предусмотренные договором аренды, или состояние имущества существенно ухудшились.\n\n5. Если иное не предусмотрено договором аренды, в случае существенного нарушения арендатором сроков внесения арендной платы арендодатель вправе потребовать от него досрочного внесения арендной платы в установленный арендодателем срок. При этом арендодатель не вправе требовать досрочного внесения арендной платы более чем за два срока подряд.","article_title":"Статья 614. Арендная плата","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2d2deb6d72dc6da319ff6df66343bad1e60c7e031518e8297c5a1ad0a0d018f7"},{"code_id":"GK_RF_2","article_number":"615","version_date":"1994-11-30","article_text":"1. Арендатор обязан пользоваться арендованным имуществом в соответствии с условиями договора аренды, а если такие условия в договоре не определены, в соответствии с назначением имущества.\n\n2. Арендатор вправе с согласия арендодателя сдавать арендованное имущество в субаренду (поднаем) и передавать свои права и обязанности по договору аренды другому лицу (перенаем), предоставлять арендованное имущество в безвозмездное пользование, а также отдавать арендные права в залог и вносить их в качестве вклада в уставный капитал хозяйственных товариществ и обществ или паевого взноса в производственный кооператив, если иное не установлено настоящим Кодексом, другим законом или иными правовыми актами. В указанных случаях, за исключением перенайма, ответственным по договору перед арендодателем остается арендатор.\n\nДоговор субаренды не может быть заключен на срок, превышающий срок договора аренды.\n\nК договорам субаренды применяются правила о договорах аренды, если иное не установлено законом или иными правовыми актами.\n\n3. Если арендатор пользуется имуществом не в соответствии с условиями договора аренды или назначением имущества, арендодатель имеет право потребовать расторжения договора и возмещения убытков.","article_title":"Статья 615. Пользование арендованным имуществом","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b051447afc1a7c8f507e3cbe492e49985568c48685e8a28e3e3d50a404f9960b"},{"code_id":"GK_RF_2","article_number":"616","version_date":"1994-11-30","article_text":"1. Арендодатель обязан производить за свой счет капитальный ремонт переданного в аренду имущества, если иное не предусмотрено законом, иными правовыми актами или договором аренды.\n\nКапитальный ремонт должен производиться в срок, установленный договором, а если он не определен договором или вызван неотложной необходимостью, в разумный срок.\n\nНарушение арендодателем обязанности по производству капитального ремонта дает арендатору право по своему выбору:\n\nпроизвести капитальный ремонт, предусмотренный договором или вызванный неотложной необходимостью, и взыскать с арендодателя стоимость ремонта или зачесть ее в счет арендной платы;\n\nпотребовать соответственного уменьшения арендной платы;\n\nпотребовать расторжения договора и возмещения убытков.\n\n2. Арендатор обязан поддерживать имущество в исправном состоянии, производить за свой счет текущий ремонт и нести расходы на содержание имущества, если иное не установлено законом или договором аренды.","article_title":"Статья 616. Обязанности сторон по содержанию арендованного имущества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3f9c36c88fdddc0cc2df5200282f55e563263e82375ba6f33a57c6bcf545b485"},{"code_id":"GK_RF_2","article_number":"617","version_date":"1994-11-30","article_text":"1. Переход права собственности (хозяйственного ведения, оперативного управления, пожизненного наследуемого владения) на сданное в аренду имущество к другому лицу не является основанием для изменения или расторжения договора аренды.\n\n2. В случае смерти гражданина, арендующего недвижимое имущество, его права и обязанности по договору аренды переходят к наследнику, если законом или договором не предусмотрено иное.\n\nАрендодатель не вправе отказать такому наследнику во вступлении в договор на оставшийся срок его действия, за исключением случая, когда заключение договора было обусловлено личными качествами арендатора.","article_title":"Статья 617. Сохранение договора аренды в силе при изменении сторон","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"76dfc228b939bc0f554c6f1309f74b6ec0a1290e12ebcb8699de5faffcd6ebf9"},{"code_id":"GK_RF_2","article_number":"618","version_date":"1994-11-30","article_text":"1. Если иное не предусмотрено договором аренды, досрочное прекращение договора аренды влечет прекращение заключенного в соответствии с ним договора субаренды. Субарендатор в этом случае имеет право на заключение с ним договора аренды на имущество, находившееся в его пользовании в соответствии с договором субаренды, в пределах оставшегося срока субаренды на условиях, соответствующих условиям прекращенного договора аренды.\n\n2. Если договор аренды по основаниям, предусмотренным настоящим Кодексом, является ничтожным, ничтожными являются и заключенные в соответствии с ним договоры субаренды.","article_title":"Статья 618. Прекращение договора субаренды при досрочном прекращении договора аренды","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b67cd9e71cb6544afe0b629df5eec7bbe3ba950d29e44e698006b8acd8199cb9"},{"code_id":"GK_RF_2","article_number":"619","version_date":"1994-11-30","article_text":"По требованию арендодателя договор аренды может быть досрочно расторгнут судом в случаях, когда арендатор:\n\n1) пользуется имуществом с существенным нарушением условий договора или назначения имущества либо с неоднократными нарушениями;\n\n2) существенно ухудшает имущество;\n\n3) более двух раз подряд по истечении установленного договором срока платежа не вносит арендную плату;\n\n4) не производит капитального ремонта имущества в установленные договором аренды сроки, а при отсутствии их в договоре в разумные сроки в тех случаях, когда в соответствии с законом, иными правовыми актами или договором производство капитального ремонта является обязанностью арендатора.\n\nДоговором аренды могут быть установлены и другие основания досрочного расторжения договора по требованию арендодателя в соответствии с пунктом 2 статьи 450 настоящего Кодекса.\n\nАрендодатель вправе требовать досрочного расторжения договора только после направления арендатору письменного предупреждения о необходимости исполнения им обязательства в разумный срок.","article_title":"Статья 619. Досрочное расторжение договора по требованию арендодателя","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"647062f9108b766d59df5dba042f8bd4162ca82d36d5839ebb4d09f881717d6c"},{"code_id":"GK_RF_2","article_number":"620","version_date":"1994-11-30","article_text":"По требованию арендатора договор аренды может быть досрочно расторгнут судом в случаях, когда:\n\n1) арендодатель не предоставляет имущество в пользование арендатору либо создает препятствия пользованию имуществом в соответствии с условиями договора или назначением имущества;\n\n2) переданное арендатору имущество имеет препятствующие пользованию им недостатки, которые не были оговорены арендодателем при заключении договора, не были заранее известны арендатору и не должны были быть обнаружены арендатором во время осмотра имущества или проверки его исправности при заключении договора;\n\n3) арендодатель не производит являющийся его обязанностью капитальный ремонт имущества в установленные договором аренды сроки, а при отсутствии их в договоре в разумные сроки;\n\n4) имущество в силу обстоятельств, за которые арендатор не отвечает, окажется в состоянии, не пригодном для использования.\n\nДоговором аренды могут быть установлены и другие основания досрочного расторжения договора по требованию арендатора в соответствии с пунктом 2 статьи 450 настоящего Кодекса.","article_title":"Статья 620. Досрочное расторжение договора по требованию арендатора","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b797506da3e448801f749fd9eed26c77412db56813c7491b77db3300b14990d8"},{"code_id":"GK_RF_2","article_number":"621","version_date":"1994-11-30","article_text":"1. Если иное не предусмотрено законом или договором аренды, арендатор, надлежащим образом исполнявший свои обязанности, по истечении срока договора имеет при прочих равных условиях преимущественное перед другими лицами право на заключение договора аренды на новый срок. Арендатор обязан письменно уведомить арендодателя о желании заключить такой договор в срок, указанный в договоре аренды, а если в договоре такой срок не указан, в разумный срок до окончания действия договора.\n\nПри заключении договора аренды на новый срок условия договора могут быть изменены по соглашению сторон.\n\nЕсли арендодатель отказал арендатору в заключении договора на новый срок, но в течение года со дня истечения срока договора с ним заключил договор аренды с другим лицом, арендатор вправе по своему выбору потребовать в суде перевода на себя прав и обязанностей по заключенному договору и возмещения убытков, причиненных отказом возобновить с ним договор аренды, либо только возмещения таких убытков.\n\n2. Если арендатор продолжает пользоваться имуществом после истечения срока договора при отсутствии возражений со стороны арендодателя, договор считается возобновленным на тех же условиях на неопределенный срок (статья 610).","article_title":"Статья 621. Преимущественное право арендатора на заключение договора аренды на новый срок","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f43780890dfe962d3ff613365eeed9d44e3bd84e256209901f682c0daedcc2b1"},{"code_id":"GK_RF_2","article_number":"622","version_date":"1994-11-30","article_text":"При прекращении договора аренды арендатор обязан вернуть арендодателю имущество в том состоянии, в котором он его получил, с учетом нормального износа или в состоянии, обусловленном договором.\n\nЕсли арендатор не возвратил арендованное имущество либо возвратил его несвоевременно, арендодатель вправе потребовать внесения арендной платы за все время просрочки. В случае, когда указанная плата не покрывает причиненных арендодателю убытков, он может потребовать их возмещения.\n\nВ случае, когда за несвоевременный возврат арендованного имущества договором предусмотрена неустойка, убытки могут быть взысканы в полной сумме сверх неустойки, если иное не предусмотрено договором.","article_title":"Статья 622. Возврат арендованного имущества арендодателю","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"197c45cfee723b859e37992a61251e15bd8d033c2af4692cc41b16d6f4e0d543"},{"code_id":"GK_RF_2","article_number":"623","version_date":"1994-11-30","article_text":"1. Произведенные арендатором отделимые улучшения арендованного имущества являются его собственностью, если иное не предусмотрено договором аренды.\n\n2. В случае, когда арендатор произвел за счет собственных средств и с согласия арендодателя улучшения арендованного имущества, не отделимые без вреда для имущества, арендатор имеет право после прекращения договора на возмещение стоимости этих улучшений, если иное не предусмотрено договором аренды.\n\n3. Стоимость неотделимых улучшений арендованного имущества, произведенных арендатором без согласия арендодателя, возмещению не подлежит, если иное не предусмотрено законом.\n\n4. Улучшения арендованного имущества, как отделимые, так и неотделимые, произведенные за счет амортизационных отчислений от этого имущества, являются собственностью арендодателя.","article_title":"Статья 623. Улучшения арендованного имущества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"88377b941aa06ff4eb56665d9f478bcce860b3b4cc6767927d7ea6ce11f345fb"},{"code_id":"GK_RF_2","article_number":"624","version_date":"1994-11-30","article_text":"1. В законе или договоре аренды может быть предусмотрено, что\n\nарендованное имущество переходит в собственность арендатора по истечении срока аренды или до его истечения при условии внесения арендатором всей обусловленной договором выкупной цены.\n\n2. Если условие о выкупе арендованного имущества не предусмотрено в договоре аренды, оно может быть установлено дополнительным соглашением сторон, которые при этом вправе договориться о зачете ранее выплаченной арендной платы в выкупную цену.\n\n3. Законом могут быть установлены случаи запрещения выкупа арендованного имущества.","article_title":"Статья 624. Выкуп арендованного имущества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bc09501fe3ca5491cbb37b807cd623918271a6e7afa605846ad150df997f938f"},{"code_id":"GK_RF_2","article_number":"625","version_date":"1994-11-30","article_text":"К отдельным видам договора аренды и договорам аренды отдельных видов имущества (прокат, аренда транспортных средств, аренда зданий и сооружений, аренда предприятий, финансовая аренда) положения, предусмотренные настоящим параграфом, применяются, если иное не установлено правилами настоящего Кодекса об этих договорах.","article_title":"Статья 625. Особенности отдельных видов аренды и аренды отдельных видов имущества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"12d9de71267f8a849de6002f7071ebaf84b09d8b16ad2a370b0bb7bfa2522064"},{"code_id":"GK_RF_2","article_number":"626","version_date":"1994-11-30","article_text":"1. По договору проката арендодатель, осуществляющий сдачу имущества в аренду в качестве постоянной предпринимательской деятельности, обязуется предоставить арендатору движимое имущество за плату во временное владение и пользование.\n\nИмущество, предоставленное по договору проката, используется для потребительских целей, если иное не предусмотрено договором или не вытекает из существа обязательства.\n\n2. Договор проката заключается в письменной форме.\n\n3. Договор проката является публичным договором (статья 426).","article_title":"Статья 626. Договор проката","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8fa5500e4839979fc5fbb9dccfeb766acd4578698b4a4a39ce1c7d260f18d3bb"},{"code_id":"GK_RF_2","article_number":"627","version_date":"1994-11-30","article_text":"1. Договор проката заключается на срок до одного года.\n\n2. Правила о возобновлении договора аренды на неопределенный срок и о преимущественном праве арендатора на возобновление договора аренды (статья 621) к договору проката не применяются.\n\n3. Арендатор вправе отказаться от договора проката в любое время, письменно предупредив о своем намерении арендодателя не менее чем за десять дней.","article_title":"Статья 627. Срок договора проката","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e9e268e7f9edd37520aed08ae555320d35b371f665b23e8f31df006be9de63ac"},{"code_id":"GK_RF_2","article_number":"628","version_date":"1994-11-30","article_text":"Арендодатель, заключающий договор проката, обязан в присутствии арендатора проверить исправность сдаваемого в аренду имущества, а также ознакомить арендатора с правилами эксплуатации имущества либо выдать ему письменные инструкции о пользовании этим имуществом.","article_title":"Статья 628. Предоставление имущества арендатору","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c0adabcce1004aae3086ad50db9bdd260ac100c943acabb8b27aaf55f9396572"},{"code_id":"GK_RF_2","article_number":"629","version_date":"1994-11-30","article_text":"1. При обнаружении арендатором недостатков сданного в аренду имущества, полностью или частично препятствующих пользованию им, арендодатель обязан в десятидневный срок со дня заявления арендатора о недостатках, если более короткий срок не установлен договором проката, безвозмездно устранить недостатки имущества на месте либо произвести замену данного имущества другим аналогичным имуществом, находящимся в надлежащем состоянии.\n\n2. Если недостатки арендованного имущества явились следствием нарушения арендатором правил эксплуатации и содержания имущества, арендатор оплачивает арендодателю стоимость ремонта и транспортировки имущества.","article_title":"Статья 629. Устранение недостатков сданного в аренду имущества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"11c0e6f21a77845ce7cf9722d2b77e1c837fabf86c3a1331e9b4d4c23917784e"},{"code_id":"GK_RF_2","article_number":"630","version_date":"1994-11-30","article_text":"1. Арендная плата по договору проката устанавливается в виде определенных в твердой сумме платежей, вносимых периодически или единовременно.\n\n2. В случае досрочного возврата имущества арендатором арендодатель возвращает ему соответствующую часть полученной арендной платы, исчисляя ее со дня, следующего за днем фактического возврата имущества.\n\n3. Взыскание с арендатора задолженности по арендной плате производится в бесспорном порядке на основе исполнительной надписи нотариуса.","article_title":"Статья 630. Арендная плата по договору проката","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cbc52aac70d6e9d9055f216908417ad8d509bfc7d0aa088c654814ddd343bc5d"},{"code_id":"GK_RF_2","article_number":"631","version_date":"1994-11-30","article_text":"1. Капитальный и текущий ремонт имущества, сданного в аренду по договору проката, является обязанностью арендодателя.\n\n2. Сдача в субаренду имущества, предоставленного арендатору по договору проката, передача им своих прав и обязанностей по договору проката другому лицу, предоставление этого имущества в безвозмездное пользование, залог арендных прав и внесение их в качестве имущественного вклада в хозяйственные товарищества и общества или паевого взноса в производственные кооперативы не допускаются.\n\n1. Аренда транспортного средства с предоставлением услуг по управлению и технической эксплуатации","article_title":"Статья 631. Пользование арендованным имуществом","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ba0e73386c4127df9c15388807a443dd4cad56b4d0ff0e04c6b321fb44b211cf"},{"code_id":"GK_RF_2","article_number":"632","version_date":"1994-11-30","article_text":"По договору аренды (фрахтования на время) транспортного средства с экипажем арендодатель предоставляет арендатору транспортное средство за плату во временное владение и пользование и оказывает своими силами услуги по управлению им и по его технической эксплуатации.\n\nПравила о возобновлении договора аренды на неопределенный срок и о преимущественном праве арендатора на заключение договора аренды на новый срок (статья 621) к договору аренды транспортного средства с экипажем не применяются.","article_title":"Статья 632. Договор аренды транспортного средства с экипажем","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e195defbbec9ce6a4d7b0edc0b2a2410be3aae306ed4a275b1a9a800230ad164"},{"code_id":"GK_RF_2","article_number":"633","version_date":"1994-11-30","article_text":"Договор аренды транспортного средства с экипажем должен быть заключен в письменной форме независимо от его срока. К такому договору не применяются правила о регистрации договоров аренды, предусмотренные пунктом 2 статьи 609 настоящего Кодекса.","article_title":"Статья 633. Форма договора аренды транспортного средства с экипажем","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a34430a03ba18d208d5de9575cdf9cc7d2c5a260355dadc82ed144e0bb41fedd"},{"code_id":"GK_RF_2","article_number":"634","version_date":"1994-11-30","article_text":"Арендодатель в течение всего срока договора аренды транспортного средства с экипажем обязан поддерживать надлежащее состояние сданного в аренду транспортного средства, включая осуществление текущего и капитального ремонта и предоставление необходимых принадлежностей.","article_title":"Статья 634. Обязанность арендодателя по содержанию транспортного средства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8808327f220b80651eaba6e28ecfc7a7f75e46b3c0b41f97219df3b633268a0b"},{"code_id":"GK_RF_2","article_number":"635","version_date":"1994-11-30","article_text":"1. Предоставляемые арендатору арендодателем услуги по управлению и технической эксплуатации транспортного средства должны обеспечивать его нормальную и безопасную эксплуатацию в соответствии с целями аренды, указанными в договоре. Договором аренды транспортного средства с экипажем может быть предусмотрен более широкий круг услуг, предоставляемых арендатору.\n\n2. Состав экипажа транспортного средства и его квалификация должны отвечать обязательным для сторон правилам и условиям договора, а если обязательными для сторон правилами такие требования не установлены, требованиям обычной практики эксплуатации транспортного средства данного вида и условиям договора.\n\nЧлены экипажа являются работниками арендодателя. Они подчиняются распоряжениям арендодателя, относящимся к управлению и технической эксплуатации, и распоряжениям арендатора, касающимся коммерческой эксплуатации транспортного средства.\n\nЕсли договором аренды не предусмотрено иное, расходы по оплате услуг членов экипажа, а также расходы на их содержание несет арендодатель.","article_title":"Статья 635. Обязанности арендодателя по управлению и технической эксплуатации транспортного средства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7ab8b1b9e92a02ebb206eceffadc34903add0ea7a08214e788e210b5b78d885f"},{"code_id":"GK_RF_2","article_number":"636","version_date":"1994-11-30","article_text":"Если иное не предусмотрено договором аренды транспортного средства с экипажем, арендатор несет расходы, возникающие в связи с коммерческой эксплуатацией транспортного средства, в том числе расходы на оплату топлива и других расходуемых в процессе эксплуатации материалов и на оплату сборов.","article_title":"Статья 636. Обязанность арендатора по оплате расходов, связанных с коммерческой эксплуатацией транспортного средства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"86cd9d009fbbff4e10e7f4503626552ee21d7cc833e33ab1a452642d70762cae"},{"code_id":"GK_RF_2","article_number":"637","version_date":"1994-11-30","article_text":"Если иное не предусмотрено договором аренды транспортного средства с экипажем, обязанность страховать транспортное средство и (или) страховать ответственность за ущерб, который может быть причинен им или в связи с его эксплуатацией, возлагается на арендодателя в тех случаях, когда такое страхование является обязательным в силу закона или договора.","article_title":"Статья 637. Страхование транспортного средства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d9d4d57fb11b13d56df241f0472bdae55b79e0765ec9f04c4ef248a3256ad16a"},{"code_id":"GK_RF_2","article_number":"638","version_date":"1994-11-30","article_text":"1. Если договором аренды транспортного средства с экипажем не предусмотрено иное, арендатор вправе без согласия арендодателя сдавать транспортное средство в субаренду.\n\n2. Арендатор в рамках осуществления коммерческой эксплуатации арендованного транспортного средства вправе без согласия арендодателя от своего имени заключать с третьими лицами договоры перевозки и иные договоры, если они не противоречат целям использования транспортного средства, указанным в договоре аренды, а если такие цели не установлены, назначению транспортного средства.","article_title":"Статья 638. Договоры с третьими лицами об использовании транспортного средства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5c496f70042e5a1fcf06abe3ea55bac60626b69378fa3b88a98a73e2d3f357f3"},{"code_id":"GK_RF_2","article_number":"639","version_date":"1994-11-30","article_text":"В случае гибели или повреждения арендованного транспортного средства арендатор обязан возместить арендодателю причиненные убытки, если последний докажет, что гибель или повреждение транспортного средства произошли по обстоятельствам, за которые арендатор отвечает в соответствии с законом или договором аренды.","article_title":"Статья 639. Ответственность за вред, причиненный транспортному средству","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a59eabbd830445e45aea4009d358a841cf099f7f8797df841691b9298b740e0d"},{"code_id":"GK_RF_2","article_number":"640","version_date":"1994-11-30","article_text":"Ответственность за вред, причиненный третьим лицам арендованным транспортным средством, его механизмами, устройствами, оборудованием, несет арендодатель в соответствии с правилами, предусмотренными главой 59 настоящего Кодекса. Он вправе предъявить к арендатору регрессное требование о возмещении сумм, выплаченных третьим лицам, если докажет, что вред возник по вине арендатора.","article_title":"Статья 640. Ответственность за вред, причиненный транспортным средством","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a8f728efc3923d4919c86eb7956ecd9f2fbfbb85b0ccddc7141f8c5c7e121c3b"},{"code_id":"GK_RF_2","article_number":"641","version_date":"1994-11-30","article_text":"Транспортными уставами и кодексами могут быть установлены иные, помимо предусмотренных настоящим параграфом, особенности аренды отдельных видов транспортных средств с предоставлением услуг по управлению и технической эксплуатации.","article_title":"Статья 641. Особенности аренды отдельных видов транспортных средств","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9f120bdb9e77288c22a49f083b816677c1dfc98e85f01abf89aa343e796cb401"},{"code_id":"GK_RF_2","article_number":"642","version_date":"1994-11-30","article_text":"По договору аренды транспортного средства без экипажа арендодатель предоставляет арендатору транспортное средство за плату во временное владение и пользование без оказания услуг по управлению им и его технической эксплуатации.\n\nПравила о возобновлении договора аренды на неопределенный срок и о преимущественном праве арендатора на заключение договора аренды на новый срок (статья 621) к договору аренды транспортного средства без экипажа не применяются.","article_title":"Статья 642. Договор аренды транспортного средства без экипажа","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0eb8145d7ff4cdc163ef5b137a8446ccaabd60aabdb5c4c45c8231057b1073da"},{"code_id":"GK_RF_2","article_number":"643","version_date":"1994-11-30","article_text":"Договор аренды транспортного средства без экипажа должен быть заключен в письменной форме независимо от его срока. К такому договору не применяются правила о регистрации договоров аренды, предусмотренные пунктом 2 статьи 609 настоящего Кодекса.","article_title":"Статья 643. Форма договора аренды транспортного средства без экипажа","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7246660edd4d213a31a2a56988769c0fdbe2ee7c1bc4d5136ba7e5220259a15a"},{"code_id":"GK_RF_2","article_number":"644","version_date":"1994-11-30","article_text":"Арендатор в течение всего срока договора аренды транспортного средства без экипажа обязан поддерживать надлежащее состояние арендованного транспортного средства, включая осуществление текущего и капитального ремонта.","article_title":"Статья 644. Обязанность арендатора по содержанию транспортного средства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"41c781ad2ca72cdd8ee8d073b984f5752d478b8bbf8137f31ab5ae111bcd662c"},{"code_id":"GK_RF_2","article_number":"645","version_date":"1994-11-30","article_text":"Арендатор своими силами осуществляет управление арендованным транспортным средством и его эксплуатацию, как коммерческую, так и техническую.","article_title":"Статья 645. Обязанности арендатора по управлению транспортным средством и по его технической эксплуатации","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c78e1af3f3db90103805f7a3fa04235682ae79b7964baffa106cc1693732334f"},{"code_id":"GK_RF_2","article_number":"646","version_date":"1994-11-30","article_text":"Если иное не предусмотрено договором аренды транспортного средства без экипажа, арендатор несет расходы на содержание арендованного транспортного средства, его страхование, включая страхование своей ответственности, а также расходы, возникающие в связи с его эксплуатацией.","article_title":"Статья 646. Обязанность арендатора по оплате расходов на содержание транспортного средства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"254e62727db45480750a5671cfd6f69e794ac4ed32693ba715d8f048a9f9c767"},{"code_id":"GK_RF_2","article_number":"647","version_date":"1994-11-30","article_text":"1. Если договором аренды транспортного средства без экипажа не предусмотрено иное, арендатор вправе без согласия арендодателя сдавать арендованное транспортное средство в субаренду на условиях договора аренды транспортного средства с экипажем или без экипажа.\n\n2. Арендатор вправе без согласия арендодателя от своего имени заключать с третьими лицами договоры перевозки и иные договоры, если они не противоречат целям использования транспортного средства, указанным в договоре аренды, а если такие цели не установлены, назначению транспортного средства.","article_title":"Статья 647. Договоры с третьими лицами об использовании транспортного средства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"124210ebf54760d93258dc70bc3183c873f83113f69ccf520d136ad6cff89af3"},{"code_id":"GK_RF_2","article_number":"648","version_date":"1994-11-30","article_text":"Ответственность за вред, причиненный третьим лицам транспортным средством, его механизмами, устройствами, оборудованием, несет арендатор в соответствии с правилами главы 59 настоящего Кодекса.","article_title":"Статья 648. Ответственность за вред, причиненный транспортным средством","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3e6dee0893610b1a163ab74766782d09392507161f5151e1619dbfc2f1461d52"},{"code_id":"GK_RF_2","article_number":"649","version_date":"1994-11-30","article_text":"Транспортными уставами и кодексами могут быть установлены иные, помимо предусмотренных настоящим параграфом, особенности аренды отдельных видов транспортных средств без предоставления услуг по управлению и технической эксплуатации.","article_title":"Статья 649. Особенности аренды отдельных видов транспортных средств","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fbd601c501eac97934bdcd54d4761984121dc455bcb92a3f3a9355192108f498"},{"code_id":"GK_RF_2","article_number":"650","version_date":"1994-11-30","article_text":"1. По договору аренды здания или сооружения арендодатель обязуется передать во временное владение и пользование или во временное пользование арендатору здание или сооружение.\n\n2. Правила настоящего параграфа применяются к аренде предприятий, если иное не предусмотрено правилами настоящего Кодекса об аренде предприятия.","article_title":"Статья 650. Договор аренды здания или сооружения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ddcbdcb8d5228c2daab19a86a923765397df9b1ead123a160c535c2bc1697307"},{"code_id":"GK_RF_2","article_number":"651","version_date":"1994-11-30","article_text":"1. Договор аренды здания или сооружения заключается в письменной форме путем составления одного документа, подписанного сторонами (пункт 2 статьи 434).\n\nНесоблюдение формы договора аренды здания или сооружения влечет его недействительность.\n\n2. Договор аренды здания или сооружения, заключенный на срок не менее года, подлежит государственной регистрации и считается заключенным с момента такой регистрации.","article_title":"Статья 651. Форма и государственная регистрация договора аренды здания или сооружения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"86cb650e45dcf4a9b92c512ae7443b07e90e15a12f3877876c927cf657460938"},{"code_id":"GK_RF_2","article_number":"652","version_date":"1994-11-30","article_text":"Если договором не определено передаваемое арендатору право на соответствующий земельный участок, к нему переходит на срок аренды здания или сооружения право пользования земельным участком, который занят зданием или сооружением и необходим для его использования в соответствии с его назначением. (В редакции Федерального закона от 26.06.2007 № 118-ФЗ)","article_title":"Статья 652. Права на земельный участок при аренде находящегося на нем здания или сооружения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e33f7274ce24c850673f867fe52efe5dfb380efbbe7091a3a77c6fbd2082310d"},{"code_id":"GK_RF_2","article_number":"653","version_date":"1994-11-30","article_text":"В случаях, когда земельный участок, на котором находится арендованное здание или сооружение, продается другому лицу, за арендатором этого здания или сооружения сохраняется право пользования земельным участком, который занят зданием или сооружением и необходим для его использования, на условиях, действовавших до продажи земельного участка. (В редакции Федерального закона от 26.06.2007 № 118-ФЗ)","article_title":"Статья 653. Сохранение арендатором здания или сооружения права пользования земельным участком при его продаже","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fcea3e57c017fa9c390ae886108ca883b9b1ce58519ecd962e10051838d7b02a"},{"code_id":"GK_RF_2","article_number":"654","version_date":"1994-11-30","article_text":"1. Договор аренды здания или сооружения должен предусматривать размер арендной платы. При отсутствии согласованного сторонами в письменной форме условия о размере арендной платы договор аренды здания или сооружения считается незаключенным. При этом правила определения цены, предусмотренные пунктом 3 статьи 424 настоящего Кодекса, не применяются.\n\n2. Установленная в договоре аренды здания или сооружения плата за пользование зданием или сооружением включает плату за пользование земельным участком, на котором оно расположено, или передаваемой вместе с ним соответствующей частью участка, если иное не предусмотрено законом или договором.\n\n3. В случаях, когда плата за аренду здания или сооружения установлена в договоре на единицу площади здания (сооружения) или иного показателя его размера, арендная плата определяется исходя из фактического размера переданного арендатору здания или сооружения.","article_title":"Статья 654. Размер арендной платы","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7f164e4c0e8f22a305d18876e98b2a095fd0ad497886da3a8561c44ab4efe3dc"},{"code_id":"GK_RF_2","article_number":"655","version_date":"1994-11-30","article_text":"1. Передача здания или сооружения арендодателем и принятие его арендатором осуществляются по передаточному акту или иному документу о передаче, подписываемому сторонами.\n\nЕсли иное не предусмотрено законом или договором аренды здания или сооружения, обязательство арендодателя передать здание или сооружение арендатору считается исполненным после предоставления его арендатору во владение или пользование и подписания сторонами соответствующего документа о передаче.\n\nУклонение одной из сторон от подписания документа о передаче здания или сооружения на условиях, предусмотренных договором, рассматривается как отказ соответственно арендодателя от исполнения обязанности по передаче имущества, а арендатора от принятия имущества.\n\n2. При прекращении договора аренды здания или сооружения арендованное здание или сооружение должно быть возвращено арендодателю с соблюдением правил, предусмотренных пунктом 1 настоящей статьи.","article_title":"Статья 655. Передача здания или сооружения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"720eacb14a1149f66ac8b40bb20d20c3052195596f894f6dc8ea223ad31bed0f"},{"code_id":"GK_RF_2","article_number":"657","version_date":"1994-11-30","article_text":"1. Кредиторы по обязательствам, включенным в состав предприятия, должны быть до его передачи арендатору письменно уведомлены арендодателем о передаче предприятия в аренду.\n\n2. Кредитор, который письменно не сообщил арендодателю о своем согласии на перевод долга, вправе в течение трех месяцев со дня получения уведомления о передаче предприятия в аренду потребовать прекращения и\n\nли досрочного исполнения обязательства и возмещения причиненных этим убытков.\n\n3. Кредитор, который не был уведомлен о передаче предприятия в аренду в порядке, предусмотренном пунктом 1 настоящей статьи, может предъявить иск об удовлетворении требований, предусмотренных пунктом 2 настоящей статьи, в течение года со дня, когда он узнал или должен был узнать о передаче предприятия в аренду.\n\n4. После передачи предприятия в аренду арендодатель и арендатор несут солидарную ответственность по включенным в состав переданного предприятия долгам, которые были переведены на арендатора без согласия кредитора.","article_title":"Статья 657. Права кредиторов при аренде предприятия","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1cce175e089874aca49b106e39df16b8773eb5d63c3c273cc5ee92d227b16a3e"},{"code_id":"GK_RF_2","article_number":"658","version_date":"1994-11-30","article_text":"1. Договор аренды предприятия заключается в письменной форме путем составления одного документа, подписанного сторонами (пункт 2 статьи 434).\n\n2. Договор аренды предприятия подлежит государственной регистрации и считается заключенным с момента такой регистрации.\n\n3. Несоблюдение формы договора аренды предприятия влечет его недействительность.","article_title":"Статья 658. Форма и государственная регистрация договора аренды предприятия","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fdcdb19e034b2a765500e9a588baef10bc4527168fe908cc9a79d7643fce1f0d"},{"code_id":"GK_RF_2","article_number":"659","version_date":"1994-11-30","article_text":"Передача предприятия арендатору осуществляется по передаточному акту.\n\nПодготовка предприятия к передаче, включая составление и представление на подписание передаточного акта, является обязанностью арендодателя и осуществляется за его счет, если иное не предусмотрено договором аренды предприятия.","article_title":"Статья 659. Передача арендованного предприятия","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c7125546a08159962239d5a83776578d38d9b377088121203c513b91aa28497f"},{"code_id":"GK_RF_2","article_number":"660","version_date":"1994-11-30","article_text":"Если иное не предусмотрено договором аренды предприятия, арендатор вправе без согласия арендодателя продавать, обменивать, предоставлять во временное пользование либо взаймы материальные ценности, входящие в состав имущества арендованного предприятия, сдавать их в субаренду и передавать свои права и обязанности по договору аренды в отношении таких ценностей другому лицу при условии, что это не влечет уменьшения стоимости предприятия и не нарушает других положений договора аренды предприятия. Указанный порядок не применяется в отношении земли и других природных ресурсов, а также в иных случаях, предусмотренных законом.\n\nЕсли иное не предусмотрено договором аренды предприятия, арендатор вправе без согласия арендодателя вносить изменения в состав арендованного имущественного комплекса, проводить его реконструкцию, расширение, техническое перевооружение, увеличивающее его стоимость.","article_title":"Статья 660. Пользование имуществом арендованного предприятия","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2cf70097213eb4ab34ed96180e2aef8443acdb92da112a78fee1d7e181283450"},{"code_id":"GK_RF_2","article_number":"661","version_date":"1994-11-30","article_text":"1. Арендатор предприятия обязан в течение всего срока действия договора аренды предприятия поддерживать предприятие в надлежащем техническом состоянии, в том числе осуществление его текущего и капитального ремонта.\n\n2. На арендатора возлагаются расходы, связанные с эксплуатацией арендованного предприятия, если иное не предусмотрено договором, а также с уплатой платежей по страхованию арендованного имущества.","article_title":"Статья 661. Обязанности арендатора по содержанию предприятия и оплате расходов на его эксплуатацию","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ab35d942ef84e7c813114a2b3b61985c01a97c76d4daa533afe2d21d38d1bd0e"},{"code_id":"GK_RF_2","article_number":"662","version_date":"1994-11-30","article_text":"Арендатор предприятия имеет право на возмещение ему стоимости неотделимых улучшений арендованного имущества независимо от разрешения арендодателя на такие улучшения, если иное не предусмотрено договором аренды предприятия.\n\nАрендодатель может быть освобожден судом от обязанности возместить арендатору стоимость таких улучшений, если докажет, что издержки арендатора на эти улучшения повышают стоимость арендованного имущества несоразмерно улучшению его качества и (или) эксплуатационных свойств или при осуществлении таких улучшений были нарушены принципы добросовестности и разумности.","article_title":"Статья 662. Внесение арендатором улучшений в арендованное предприятие","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"041539031afc219a43091756c75d00357452b00cd0e27c28333e9ac4c0ba5632"},{"code_id":"GK_RF_2","article_number":"663","version_date":"1994-11-30","article_text":"Правила настоящего Кодекса о последствиях недействительности сделок, об изменении и о расторжении договора, предусматривающие возврат или взыскание в натуре полученного по договору с одной стороны или с обеих сторон, применяются к договору аренды предприятия, если такие последствия не нарушают существенно права и охраняемые законом интересы кредиторов арендодателя и арендатора, других лиц и не противоречат общественным интересам.","article_title":"Статья 663. Применение к договору аренды предприятия правил о последствиях недействительности сделок, об изменении и о расторжении договора","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0a83b7124259dae6e573b4694b07b2820bb40a5d1f490856b48e4af122e9f0f3"},{"code_id":"GK_RF_2","article_number":"664","version_date":"1994-11-30","article_text":"При прекращении договора аренды предприятия арендованный имущественный комплекс должен быть возвращен арендодателю с соблюдением правил, предусмотренных статьями 656, 657 и 659 настоящего Кодекса. Подготовка предприятия к передаче арендодателю, включая составление и представление на подписание передаточного акта, является в этом случае обязанностью арендатора и осуществляется за его счет, если иное не предусмотрено договором.","article_title":"Статья 664. Возврат арендованного предприятия","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b389f39be541d761b7b2633bb53f9ac7465427100fcdcb3278c5c71a5bec122b"},{"code_id":"GK_RF_2","article_number":"665","version_date":"1994-11-30","article_text":"По договору финансовой аренды (договору лизинга) арендодатель обязуется приобрести в собственность указанное арендатором имущество у определенного им продавца и предоставить арендатору это имущество за плату во временное владение и пользование. Арендодатель в этом случае не несет ответственности за выбор предмета аренды и продавца. (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\nДоговором финансовой аренды может быть предусмотрено, что выбор продавца и приобретаемого имущества осуществляется арендодателем.\n\nЧасть. (Дополнение частью - Федеральный закон от 08.05.2010 № 83-ФЗ) (Утратила силу - Федеральный закон от 31.12.2014 № 512-ФЗ)\n\nОсобенности договора финансовой аренды (договора лизинга), заключаемого государственным или муниципальным учреждением, устанавливаются Федеральным законом от 29 октября 1998 года № 164-ФЗ \"О финансовой аренде (лизинге)\".  (Дополнение частью - Федеральный закон от 31.12.2014 № 512-ФЗ)","article_title":"Статья 665. Договор финансовой аренды","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"616f940c6108751220bf2976b659f76df461101e509e8530b7b1a9636f182f42"},{"code_id":"GK_RF_2","article_number":"666","version_date":"1994-11-30","article_text":"Предметом договора финансовой аренды могут быть любые непотребляемые вещи, кроме земельных участков и других природных объектов. (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)","article_title":"Статья 666. Предмет договора финансовой аренды","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"960ae10fc708d424000db33855bc664ab33b090700736d983a266d1c46d85715"},{"code_id":"GK_RF_2","article_number":"667","version_date":"1994-11-30","article_text":"Арендодатель, приобретая имущество для арендатора, должен уведомить продавца о том, что имущество предназначено для передачи его в аренду определенному лицу.","article_title":"Статья 667. Уведомление продавца о сдаче имущества в аренду","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"28dfe76785b62a09e6ab12c31e8cee33418d79fe4d7547324edda50d7da4dbea"},{"code_id":"GK_RF_2","article_number":"668","version_date":"1994-11-30","article_text":"1. Если иное не предусмотрено договором финансовой аренды, имущество, являющееся предметом этого договора, передается продавцом непосредственно арендатору в месте нахождения последнего.\n\n2. В случае, когда имущество, являющееся предметом договора финансовой аренды, не передано арендатору в указанный в этом договоре срок, а если в договоре такой срок не указан, в разумный срок, арендатор вправе, если просрочка допущена по обстоятельствам, за которые отвечает арендодатель, потребовать расторжения договора и возмещения убытков.","article_title":"Статья 668. Передача арендатору предмета договора финансовой аренды","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"91b34d92056bc6f76041101d160b85d85914415f4f8a3a1efd90858f8cb9c323"},{"code_id":"GK_RF_2","article_number":"669","version_date":"1994-11-30","article_text":"Риск случайной гибели или случайной порчи арендованного имущества переходит к арендатору в момент передачи ему арендованного имущества, если иное не предусмотрено договором финансовой аренды.","article_title":"Статья 669. Переход к арендатору риска случайной гибели или случайной порчи имущества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ac6941fd03d230e0652a755e7f15eceeb14aefcb01bcb3508354f99626e7bfd8"},{"code_id":"GK_RF_2","article_number":"670","version_date":"1994-11-30","article_text":"1. Арендатор вправе предъявлять непосредственно продавцу имущества, являющегося предметом договора финансовой аренды, требования, вытекающие из договора купли-продажи, заключенного между продавцом и арендодателем, в частности в отношении качества и комплектности имущества, сроков его поставки, и в других случаях ненадлежащего исполнения договора продавцом. При этом арендатор имеет права и несет обязанности, предусмотренные настоящим Кодексом для покупателя, кроме обязанности оплатить приобретенное имущество, как если бы он был стороной договора купли-продажи указанного имущества. Однако арендатор не может расторгнуть договор купли-продажи с продавцом без согласия арендодателя.\n\nВ отношениях с продавцом арендатор и арендодатель выступают как солидарные кредиторы (статья 326).\n\n2. Если иное не предусмотрено договором финансовой аренды, арендодатель не отвечает перед арендатором за выполнение продавцом требований, вытекающих из договора купли-продажи, кроме случаев, когда ответственность за выбор продавца лежит на арендодателе. В последнем случае арендатор вправе по своему выбору предъявлять требования, вытекающие из договора купли-продажи, как непосредственно продавцу имущества, так и арендодателю, которые несут солидарную ответственность.","article_title":"Статья 670. Ответственность продавца","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"10cf7a550832a2cf05a37989413d1399889c506a02c84b220007e7b6d3b492ce"},{"code_id":"GK_RF_2","article_number":"671","version_date":"1994-11-30","article_text":"1. По договору найма жилого помещения одна сторона - собственник жилого помещения или управомоченное им лицо (наймодатель) - обязуется предоставить другой стороне (нанимателю) жилое помещение за плату во владение и пользование для проживания в нем.\n\n2. Юридическим лицам жилое помещение может быть предоставлено во владение и (или) пользование на основе договора аренды или иного договора. Юридическое лицо может использовать жилое помещение только для проживания граждан.","article_title":"Статья 671. Договор найма жилого помещения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0f95ec62f605fe07835c2a26f1af9d9079c26a682397f8d75cad72b199ec09eb"},{"code_id":"GK_RF_2","article_number":"672","version_date":"1994-11-30","article_text":"(Наименование в редакции Федерального закона от 21.07.2014 № 217-ФЗ)\n\nПо требованию нанимателя и членов его семьи договор может быть заключен с одним из членов семьи. В случае смерти нанимателя или его выбытия из жилого помещения договор заключается с одним из членов семьи, проживающих в жилом помещении.","article_title":"Статья 672. Договор найма жилого помещения в жилищном фонде социального использования","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"108aa5ebbb9673e948cca7aa8c0da5394943b4a0c6115c6315e40a4b2bb5e87a"},{"code_id":"GK_RF_2","article_number":"673","version_date":"1994-11-30","article_text":"1. Объектом договора найма жилого помещения может быть изолированное жилое помещение, пригодное для постоянного проживания (квартира, жилой дом, часть квартиры или жилого дома).\n\nПригодность жилого помещения для проживания определяется в порядке, предусмотренном жилищным законодательством.\n\n2. Наниматель жилого помещения в многоквартирном доме наряду с пользованием жилым помещением имеет право пользоваться имуществом, указанным в статье 290 настоящего Кодекса.","article_title":"Статья 673. Объект договора найма жилого помещения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2c97ad227598987be90c3ee8bbc5259c0c34697c768b6f6215fafd7fca8bfefb"},{"code_id":"GK_RF_2","article_number":"675","version_date":"1994-11-30","article_text":"Переход права собственности на занимаемое по договору найма жилое помещение не влечет расторжения или изменения договора найма жилого помещения. При этом новый собственник становится наймодателем на условиях ранее заключенного договора найма.","article_title":"Статья 675. Сохранение договора найма жилого помещения при переходе права собственности на жилое помещение","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0c0d2793c126a6b8d09abc65a451ef61f1a664b7af65e80889d5e1e5610fe879"},{"code_id":"GK_RF_2","article_number":"676","version_date":"1994-11-30","article_text":"1. Наймодатель обязан передать нанимателю свободное жилое помещение в состоянии, пригодном для проживания.\n\n2. Наймодатель обязан осуществлять надлежащую эксплуатацию жилого дома, в котором находится сданное внаем жилое помещение, предоставлять или обеспечивать предоставление нанимателю за плату необходимых коммунальных услуг, обеспечивать проведение ремонта общего имущества многоквартирного дома и устройств для оказания коммунальных услуг, находящихся в жилом помещении.","article_title":"Статья 676. Обязанности наймодателя жилого помещения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"79be0f549fc4b5455f45fbcd998ce5788bcbc7b0fd5f2e2bbf3d9adf56caa82a"},{"code_id":"GK_RF_2","article_number":"677","version_date":"1994-11-30","article_text":"1. Нанимателем по договору найма жилого помещения может быть только гражданин.\n\n2. В договоре должны быть указаны граждане, постоянно проживающие в жилом помещении вместе с нанимателем. При отсутствии в договоре таких указаний вселение этих граждан производится в соответствии с правилами статьи 679 настоящего Кодекса.\n\nГраждане, постоянно проживающие совместно с нанимателем, имеют равные с ним права по пользованию жилым помещением. Отношения между нанимателем и такими гражданами определяются законом.\n\n3. Наниматель несет ответственность перед наймодателем за действия граждан, постоянно проживающих совместно с ним, которые нарушают условия договора найма жилого помещения.\n\n4. Граждане, постоянно проживающие вместе с нанимателем, могут, известив наймодателя, заключить с нанимателем договор о том, что все граждане, постоянно проживающие в жилом помещении, несут совместно с нанимателем солидарную ответственность перед наймодателем. В этом случае такие граждане являются сонанимателями.","article_title":"Статья 677. Наниматель и постоянно проживающие вместе с ним граждане","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"38459c1117fdab69950ecf2c8321232c8635660cafba899f23c3d96516774f99"},{"code_id":"GK_RF_2","article_number":"678","version_date":"1994-11-30","article_text":"Наниматель обязан использовать жилое помещение только для проживания, обеспечивать сохранность жилого помещения и поддерживать его в надлежащем состоянии.\n\nНаниматель не вправе производить переустройство и реконструкцию жилого помещения без согласия наймодателя.\n\nНаниматель обязан своевременно вносить плату за жилое помещение. Если договором не установлено иное, наниматель обязан самостоятельно вносить коммунальные платежи.","article_title":"Статья 678. Обязанности нанимателя жилого помещения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"08b0acbfbfe666630445522a15f6cacc49b5713f65df84ca81447d31767961fc"},{"code_id":"GK_RF_2","article_number":"679","version_date":"1994-11-30","article_text":"С согласия наймодателя, нанимателя и граждан, постоянно с ним проживающих, в жилое помещение могут быть вселены другие граждане в качестве постоянно проживающих с нанимателем. При вселении несовершеннолетних детей такого согласия не требуется.\n\nВселение допускается при условии соблюдения требований законодательства о норме общей площади жилого помещения на одного человека, кроме случая вселения несовершеннолетних детей. (В редакции Федерального закона от 29.12.2004 № 189-ФЗ)","article_title":"Статья 679. Вселение граждан, постоянно проживающих с нанимателем","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"dc3fbf19a495c9b003ec290ed8c2806a5f576e3fc638b6a6af544cea141c794c"},{"code_id":"GK_RF_2","article_number":"680","version_date":"1994-11-30","article_text":"Наниматель и граждане, постоянно с ним проживающие, по общему согласию и с предварительным уведомлением наймодателя вправе разрешить безвозмездное проживание в жилом помещении временным жильцам (пользователям). Наймодатель может запретить проживание временных жильцов при условии несоблюдения требований законодательства о норме общей площади жилого помещения на одного человека. Срок проживания временных жильцов не может превышать шесть месяцев.  (В редакции Федерального закона от 29.12.2004 № 189-ФЗ)\n\nВременные жильцы не обладают самостоятельным правом пользования жилым помещением. Ответственность за их действия перед наймодателем несет наниматель.\n\nВременные жильцы обязаны освободить жилое помещение по истечении согласованного с ними срока проживания, а если срок не согласован, не позднее семи дней со дня предъявления соответствующего требования нанимателем или любым гражданином, постоянно с ним проживающим.","article_title":"Статья 680. Временные жильцы","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0ac77810b4f057bcd49d1c982f1a594487e2e8054d764d9fc680c3b7e8348c0c"},{"code_id":"GK_RF_2","article_number":"681","version_date":"1994-11-30","article_text":"1. Текущий ремонт сданного внаем жилого помещения является обязанностью нанимателя, если иное не установлено договором найма жилого помещения.\n\n2. Капитальный ремонт сданного внаем жилого помещения является обязанностью наймодателя, если иное не установлено договором найма жилого помещения.\n\n3. Переоборудование жилого дома, в котором находится сданное внаем жилое помещение, если такое переоборудование существенно изменяет условия пользования жилым помещением, без согласия нанимателя не допускается.","article_title":"Статья 681. Ремонт сданного внаем жилого помещения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"90e657192cb880b7c459f315c63dd24e449b5390d65c38b9c9fbdfc5b5498caf"},{"code_id":"GK_RF_2","article_number":"682","version_date":"1994-11-30","article_text":"1. Размер платы за жилое помещение устанавливается по соглашению сторон в договоре найма жилого помещения. В случае, если в соответствии с законом установлен максимальный размер платы за жилое помещение, плата, установленная в договоре, не должна превышать этот размер.\n\n2. Одностороннее изменение размера платы за жилое помещение не допускается, за исключением случаев, предусмотренных законом или договором.\n\n3. Плата за жилое помещение должна вноситься нанимателем в сроки, предусмотренные договором найма жилого помещения. Если договором сроки не предусмотрены, плата должна вноситься нанимателем ежемесячно в порядке, установленном Жилищным кодексом Российской Федерации.","article_title":"Статья 682. Плата за жилое помещение","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"53f45ada2d64cfcda3a3d7018cc43bc1790dd8ae46f5353a521657d62621678d"},{"code_id":"GK_RF_2","article_number":"683","version_date":"1994-11-30","article_text":"1. Договор найма жилого помещения заключается на срок, не превышающий пяти лет. Если в договоре срок не определен, договор считается заключенным на пять лет.\n\n2. К договору найма жилого помещения, заключенному на срок до одного года (краткосрочный наем), не применяются правила, предусмотренные пунктом 2 статьи 677, статьями 680, 684 - 686, абзацем четвертым пункта 2 статьи 687 настоящего Кодекса, если договором не предусмотрено иное.","article_title":"Статья 683. Срок в договоре найма жилого помещения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3a141bcc53b9f2c229ebdd66310a8f15d4860ba82e829a7fd9d8ee6c08132117"},{"code_id":"GK_RF_2","article_number":"684","version_date":"1994-11-30","article_text":"По истечении срока договора найма жилого помещения наниматель имеет преимущественное право на заключение договора найма жилого помещения на новый срок.\n\nНе позднее чем за три месяца до истечения срока договора найма жилого помещения наймодатель должен предложить нанимателю заключить договор на тех же или иных условиях либо предупредить нанимателя об отказе от продления договора в связи с решением не сдавать в течение не менее года жилое помещение внаем. Если наймодатель не выполнил этой обязанности, а наниматель не отказался от продления договора, договор считается продленным на тех же условиях и на тот же срок.\n\nПри согласовании условий договора наниматель не вправе требовать увеличения числа лиц, постоянно с ним проживающих по договору найма жилого помещения.\n\nЕсли наймодатель отказался от продления договора в связи с решением не сдавать помещение внаем, но в течение года со дня истечения срока договора с нанимателем заключил договор найма жилого помещения с другим лицом, наниматель вправе требовать признания такого договора недействительным и (или) возмещения убытков, причиненных отказом возобновить с ним договор.","article_title":"Статья 684. Преимущественное право нанимателя на заключение договора на новый срок","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e6e31d4de0ec2deb1dcd56853adfd38c48a1bc8df5e9b1f723c2b42a6f50cd14"}]$law7v014$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text)) insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at) select code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,'70a1d8fc6b27b67ad7f12f03f017d02b5f68a0c895447159039800965895f8b2',now() from j on conflict (code_id,article_number,version_date) do update set article_text=excluded.article_text,article_title=excluded.article_title,amendment_eo_number=excluded.amendment_eo_number,amendment_date=excluded.amendment_date,is_current=excluded.is_current,is_repealed=excluded.is_repealed,repealed_date=excluded.repealed_date,text_hash=excluded.text_hash,source_commit=excluded.source_commit,imported_at=now();
    commit;
